function flipDigits(x: number): number {
  const MAX_TENTH = 214748364; // 2147483647 / 10, rounded toward zero
  let result = 0;
  while (x !== 0) {
    const digit = x % 10; // keeps x's sign in JS: -305 % 10 === -5
    x = Math.trunc(x / 10);
    if (result > MAX_TENTH || (result === MAX_TENTH && digit > 7)) return 0;
    if (result < -MAX_TENTH || (result === -MAX_TENTH && digit < -8)) return 0;
    result = result * 10 + digit;
  }
  return result;
}

